mapper.sql:
FROM solution_explanation s
LEFT JOIN solution_problem_reference r ON r.problem_id = s.problem_id
WHERE s.del_flag = 0

    AND s.user_id = #{filterUserId}


    AND s.problem_id = #{problemId}



        AND s.`private` = 0 AND s.moderation_state = 'NORMAL'
        AND r.exists_flag = 1 AND r.del_flag = 0 AND r.auth = 1





        AND (
            s.user_id = #{viewerId}
            OR (s.`private` = 0 AND s.moderation_state = 'NORMAL'
                AND r.exists_flag = 1 AND r.del_flag = 0 AND r.auth = 1)
        )

mapper.select:
SELECT s.solution_id, s.problem_id, s.user_id, s.`private`, s.del_flag, s.moderation_state
FROM solution_explanation s
WHERE s.solution_id = #{solutionId}

mapper.update:
UPDATE solution_explanation
SET like_count = like_count + #{delta}
WHERE solution_id = #{solutionId} AND like_count + #{delta} >= 0

UPDATE solution_explanation
SET comment_count = comment_count + #{delta}
WHERE solution_id = #{solutionId} AND comment_count + #{delta} >= 0

mapper.select:
SELECT s.solution_id, s.problem_id, s.user_id, s.version, s.top_up, s.create_time


    AND (
        COALESCE(s.top_up, 0) < COALESCE(#{cursor.topUp}, 0)
        OR (COALESCE(s.top_up, 0) = COALESCE(#{cursor.topUp}, 0)
            AND s.create_time < #{cursor.createTime})
        OR (COALESCE(s.top_up, 0) = COALESCE(#{cursor.topUp}, 0)
            AND s.create_time = #{cursor.createTime}
            AND s.solution_id < #{cursor.solutionId})
    )

ORDER BY COALESCE(s.top_up, 0) DESC, s.create_time DESC, s.solution_id DESC

    LIMIT #{limit}
    LIMIT #{offset}, #{limit}

mapper.update:
UPDATE solution_explanation
SET top_up = #{topUp}, update_time = CURRENT_TIMESTAMP(3), version = version + 1
WHERE solution_id = #{solutionId} AND del_flag = 0 AND version = #{version}
